// Copies third-party licence texts into the deployed folder so they ship with the app.
// Runs after `ng build` (see the "build" script in package.json).
import { copyFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';

const dist = 'dist/cmdvault';
const out = join(dist, 'browser', 'licenses');

const files = [
  // Generated by the Angular CLI from the JavaScript packages in the bundle.
  { from: join(dist, '3rdpartylicenses.txt'), to: 'third-party.txt' },
  // Fonts are bundled from CSS, so the CLI doesn't list them. Copy their OFL texts.
  { from: 'node_modules/@fontsource-variable/inter/LICENSE', to: 'fonts/inter.txt' },
  { from: 'node_modules/@fontsource-variable/space-grotesk/LICENSE', to: 'fonts/space-grotesk.txt' },
  { from: 'node_modules/@fontsource-variable/jetbrains-mono/LICENSE', to: 'fonts/jetbrains-mono.txt' },
  { from: 'LICENSE', to: 'cmdvault.txt' },
];

for (const { from, to } of files) {
  if (!existsSync(from)) {
    console.error(`copy-licenses: missing ${from}`);
    process.exit(1);
  }
  const target = join(out, to);
  mkdirSync(dirname(target), { recursive: true });
  copyFileSync(from, target);
}
console.log(`copy-licenses: wrote ${files.length} files to ${out}`);
